        p=p.strip()
        if p: parts[p]+=1
listed=set(targets)|{p for p in parts if p not in targets}
def mtext(c):
    return "".join(b if isinstance(b,str) else b.get('text','') for b in c) if isinstance(c,list) else (c if isinstance(c,str) else "")
def field(txt,f):
    try:
        j=json.loads(txt)
        if isinstance(j,dict) and f in j: return j[f]
    except Exception: pass
    m=re.search(r'"%s"\s*:\s*"((?:[^"\\]|\\.)*)"'%f, txt or "")
    return m.group(1) if m else None
def subseq(x,y):
    it=iter(y); return all(c in it for c in x)
base=f"{run}/LawBench/conversations"
nbad=0; fam=[]
for idx in sorted(os.listdir(base)):
    if not idx.isdigit(): continue
    for f in sorted(os.listdir(f"{base}/{idx}")):
        if not f.endswith('.json'): continue
        s=json.load(open(f"{base}/{idx}/{f}"))
        draft=field(mtext(s['messages'][-1].get('content')),'final_answer')
        if draft is None: continue
        r=eval_lawbench(draft, s['target'])
        if r['correct']: continue
        nbad+=1
        ents=[x.strip() for x in re.sub(r'\[罪名\]|<eoa>','',draft).split(';') if x.strip()]
        odd=[e for e in ents if e not in listed and any(l!=e and len(e)>=2 and (subseq(e,l) or (len(l)>=2 and subseq(l,e))) for l in listed)]
        if odd: fam.append((idx,f,odd,draft,s['target']))
print(f"N5 drafts scored: wrong={nbad}; carrying an entry written differently from the memory's: {len(fam)}")
for x in fam: print("   ",x[0],x[1],x[2],"gold=",x[4])
